#include <iostream>
#include <iomanip>

// Demonstrates array decay to pointer and passing array by reference
void modifyArray(int b[], std::size_t size) {
    for (std::size_t j = 0; j < size; ++j) {
        b[j] *= 2; // directly modifies elements in caller's array
    }
}

int main() {
    int a[5] = {10, 20, 30, 40, 50};

    // Verify that array name, &a[0], and &a point to the same memory address
    std::cout << "Address checks:" << std::endl;
    std::cout << "a == &a[0]: " << std::boolalpha << (static_cast<void*>(a) == static_cast<void*>(&a[0])) << std::endl;
    std::cout << "a == &a:    " << std::boolalpha << (static_cast<void*>(a) == static_cast<void*>(&a)) << std::endl;

    std::cout << "Before modification:";
    for (std::size_t i = 0; i < 5; ++i) {
        std::cout << " " << a[i];
    }
    std::cout << std::endl;

    modifyArray(a, 5);

    std::cout << "After modification:";
    for (std::size_t i = 0; i < 5; ++i) {
        std::cout << " " << a[i];
    }
    std::cout << std::endl;

    return 0;
}

#include <iostream>

// Function that receives a read-only array (Principle of Least Privilege)
void displayArray(const int b[], std::size_t size) {
    // b[0] = 99; // COMPILE ERROR: assignment of read-only location
    for (std::size_t i = 0; i < size; ++i) {
        std::cout << b[i] << " ";
    }
    std::cout << std::endl;
}

// Function that receives a single scalar element by value
void modifyScalarElement(int e) {
    e *= 2; // only modifies local copy
    std::cout << "Inside modifyScalarElement: " << e << std::endl;
}

int main() {
    int numbers[5] = {0, 1, 2, 3, 4};

    std::cout << "Original array elements: ";
    displayArray(numbers, 5);

    std::cout << "Passing scalar element numbers[3] by value:" << std::endl;
    std::cout << "Before call, numbers[3] = " << numbers[3] << std::endl;
    modifyScalarElement(numbers[3]);
    std::cout << "After call, numbers[3] = " << numbers[3] << std::endl;

    return 0;
}
